<?php

namespace App\Support;

use App\Models\ContentImage;
use Illuminate\Support\Facades\Storage;

/**
 * Resolves stored content images to real dimensions and responsive variants.
 *
 * Content images are stored under `content/{type}/YYYY/MM/...` on the public
 * disk. Each image has a base file plus optional `-{width}w.webp` variants
 * generated by ContentImageService. This helper reads dimensions from the
 * content_images table (with a getimagesize fallback) and builds srcset data
 * from the files that actually exist, so `<img>` tags can reserve space
 * (no layout shift) and serve the right size per viewport.
 */
class StoredImage
{
    public const DEFAULT_SIZES = '(min-width: 1024px) 48rem, 100vw';

    /** Widths used by ContentImageService when generating variants. */
    final public const VARIANT_WIDTHS = [320, 640, 960, 1280, 1600];

    /** @var array<string, ContentImage|null> keyed by relative path */
    private static array $rows = [];

    /** @var array<string, array{width: int, height: int}|null> keyed by relative path */
    private static array $resolved = [];

    /** @var array<string, array<int, array{src: string, width: int}>> keyed by relative path */
    private static array $variants = [];

    /** Clear per-request resolution caches (used between tests). */
    public static function flush(): void
    {
        self::$rows = [];
        self::$resolved = [];
        self::$variants = [];
    }

    /**
     * Resolve a content image URL to its native dimensions.
     *
     * @return array{width: int, height: int}|null null when the image is not a
     *         stored content image or its dimensions cannot be determined.
     */
    public static function resolve(string $url): ?array
    {
        $rel = static::toRelativePath($url);

        if ($rel === null) {
            return null;
        }

        if (array_key_exists($rel, self::$resolved)) {
            return self::$resolved[$rel];
        }

        static::loadRows([$rel]);

        $row = self::$rows[$rel] ?? null;
        if ($row instanceof ContentImage && $row->width > 0 && $row->height > 0) {
            return self::$resolved[$rel] = ['width' => $row->width, 'height' => $row->height];
        }

        try {
            $path = Storage::disk('public')->path($rel);
            if (is_file($path)) {
                $size = @getimagesize($path);
                if ($size !== false) {
                    return self::$resolved[$rel] = ['width' => $size[0], 'height' => $size[1]];
                }
            }
        } catch (\Throwable $e) {
            // fall through
        }

        return self::$resolved[$rel] = null;
    }

    /**
     * List available responsive variants (including the base image) newest
     * pixel width first. Returns [] when a single image cannot usefully be
     * served responsively.
     *
     * @return array<int, array{src: string, width: int}>
     */
    public static function variants(string $url): array
    {
        $rel = static::toRelativePath($url);

        if ($rel === null) {
            return [];
        }

        if (isset(self::$variants[$rel])) {
            return self::$variants[$rel];
        }

        $dims = static::resolve($url);
        if ($dims === null) {
            return self::$variants[$rel] = [];
        }

        $disk = Storage::disk('public');
        $info = pathinfo($rel);
        $stem = $info['dirname'].'/'.$info['filename'];

        $list = [['src' => $disk->url($rel), 'width' => $dims['width']]];

        foreach (self::VARIANT_WIDTHS as $width) {
            if ($width >= $dims['width']) {
                continue;
            }

            $variantPath = "{$stem}-{$width}w.webp";

            if ($disk->exists($variantPath)) {
                $list[] = ['src' => $disk->url($variantPath), 'width' => $width];
            }
        }

        usort($list, fn (array $a, array $b) => $b['width'] <=> $a['width']);

        return self::$variants[$rel] = count($list) > 1 ? $list : [];
    }

    public static function srcset(string $url): ?string
    {
        $variants = static::variants($url);

        if ($variants === []) {
            return null;
        }

        return implode(', ', array_map(
            fn (array $variant) => $variant['src'].' '.$variant['width'].'w',
            $variants
        ));
    }

    /**
     * Inject `width`, `height`, `srcset` and `sizes` into every `<img>` tag
     * that references a stored content image. Tags pointing elsewhere are
     * left untouched.
     */
    public static function decorate(string $html, string $sizes = self::DEFAULT_SIZES): string
    {
        $paths = [];

        if (preg_match_all('/<img\b[^>]*\bsrc=["\']([^"\']+)["\']/i', $html, $matches)) {
            foreach ($matches[1] as $src) {
                $rel = static::toRelativePath($src);
                if ($rel !== null) {
                    $paths[] = $rel;
                }
            }
        }

        if ($paths === []) {
            return $html;
        }

        static::loadRows(array_unique($paths));

        return preg_replace_callback(
            '/<img\b[^>]*>/i',
            fn (array $match) => static::decorateTag($match[0], $sizes),
            $html
        ) ?? $html;
    }

    private static function decorateTag(string $tag, string $sizes): string
    {
        if (! preg_match('/\bsrc=["\']([^"\']+)["\']/i', $tag, $match)) {
            return $tag;
        }

        $dims = static::resolve($match[1]);
        if ($dims === null) {
            return $tag;
        }

        if (! preg_match('/\b(width|height)\s*=/i', $tag)) {
            $tag = preg_replace(
                '/<img\b/i',
                '<img width="'.$dims['width'].'" height="'.$dims['height'].'"',
                $tag,
                1
            ) ?? $tag;
        }

        $srcset = static::srcset($match[1]);
        if ($srcset !== null && ! preg_match('/\bsrcset\s*=/i', $tag)) {
            $tag = preg_replace(
                '/<img\b/i',
                '<img srcset="'.htmlspecialchars($srcset, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8')
                    .'" sizes="'.htmlspecialchars($sizes, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8').'"',
                $tag,
                1
            ) ?? $tag;
        }

        return $tag;
    }

    /**
     * Convert an <img> src value to the relative path on the public disk, or
     * null when the image is not one of ours (external, inline data, etc.).
     */
    private static function toRelativePath(string $url): ?string
    {
        $url = trim($url);

        if ($url === '') {
            return null;
        }

        if (preg_match('#^[a-z0-9+.\-]+://#i', $url) && ! preg_match('#^https?://#i', $url)) {
            return null;
        }

        $path = $url;
        if (preg_match('#^https?://[^/]+(/.*)?$#i', $url, $host)) {
            $path = $host[1] ?? '/';
        }

        $path = ltrim($path, '/');

        if (str_starts_with($path, 'storage/')) {
            $path = substr($path, strlen('storage/'));
        }

        if (! str_starts_with($path, 'content/')) {
            return null;
        }

        if (! preg_match('/\.(webp|png|jpe?g)$/i', $path)) {
            return null;
        }

        return $path;
    }

    /**
     * Bulk-load content image rows so a whole document resolves in one query.
     *
     * @param array<int, string> $paths
     */
    private static function loadRows(array $paths): void
    {
        $missing = array_values(array_filter(
            array_unique($paths),
            fn (string $rel) => ! array_key_exists($rel, self::$rows)
        ));

        if ($missing === []) {
            return;
        }

        foreach (ContentImage::query()->whereIn('path', $missing)->get() as $row) {
            self::$rows[$row->path] = $row;
        }

        foreach ($missing as $rel) {
            self::$rows[$rel] ??= null;
        }
    }
}